/* ------------------------------------------------------------ loading */

.loading-screen {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background:
    radial-gradient(600px 400px at 50% 40%, rgba(201, 255, 77, 0.05), transparent 60%),
    #06090b;
  transition: opacity .45s ease, visibility .45s ease;
}
.loading-screen.done { opacity: 0; visibility: hidden; pointer-events: none; }
.loader-mark {
  display: grid;
  grid-template-columns: repeat(2, 16px);
  grid-template-rows: repeat(2, 16px);
  gap: 4px;
  transform: rotate(45deg);
  animation: loaderSpin 2.4s ease-in-out infinite;
}
.loader-mark span {
  border-radius: 3px;
  background: var(--lime);
  box-shadow: 0 0 16px rgba(201, 255, 77, 0.5);
  animation: loaderBlink 1.2s ease-in-out infinite;
}
.loader-mark span:nth-child(2) { animation-delay: .15s; background: var(--cyan); box-shadow: 0 0 16px rgba(77, 232, 255, 0.5); }
.loader-mark span:nth-child(3) { animation-delay: .3s; }
.loader-mark span:nth-child(4) { animation-delay: .45s; opacity: .5; }
@keyframes loaderSpin { 0%, 100% { transform: rotate(45deg) scale(1); } 50% { transform: rotate(225deg) scale(0.9); } }
@keyframes loaderBlink { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
.loader-copy { text-align: center; }
.loader-copy b { display: block; font-size: 17px; letter-spacing: 0.18em; font-weight: 800; }
.loader-copy span { display: block; margin-top: 6px; color: var(--muted); font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; }

