  /* ---------------------------------------------------------- grid */

  resize(cols, rows) {
    cols = Math.max(24, cols | 0);
    rows = Math.max(24, rows | 0);
    if (cols === this.cols && rows === this.rows) return;
    const old = {
      cols: this.cols,
      rows: this.rows,
      cells: this.cells,
      variant: this.variant,
      temps: this.temps,
      aux: this.aux,
